import { useState, useRef, useEffect } from "react";
import axios from "axios";
import { motion, AnimatePresence } from "framer-motion";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

/* -------- Spinner Component -------- */
const Spinner = () => (
  <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></span>
);

export default function App() {

  const [code, setCode] = useState("");
  const [explanation, setExplanation] = useState("");
  const [updatedCode, setUpdatedCode] = useState("");
  const [targetLang, setTargetLang] = useState("");
  const [detectedLang, setDetectedLang] = useState("");

  const [loadingExplain, setLoadingExplain] = useState(false);
  const [loadingFix, setLoadingFix] = useState(false);
  const [loadingOptimize, setLoadingOptimize] = useState(false);
  const [loadingConvert, setLoadingConvert] = useState(false);

  const [copied, setCopied] = useState(false);
  const explanationRef = useRef(null);

  const isAnyLoading =
    loadingExplain || loadingFix || loadingOptimize || loadingConvert;

  /* -------- Explanation Cleaner (NEW) -------- */
  const cleanExplanation = (text) => {
  if (!text) return "";

  // Remove raw JSON labels if AI accidentally returns them
  return text
    .replace(/"explanation"\s*:/gi, "")
    .replace(/"updatedCode"\s*:/gi, "")
    .replace(/[{}]/g, "")
    .trim();
};

  /* -------- Language Detection -------- */
  const detectLanguage = (code) => {

    if (/print\(|def |import |from /.test(code)) return "Python";
    if (/console\.log|function |=>/.test(code)) return "JavaScript";
    if (/#include <iostream>|std::|cout/.test(code)) return "C++";
    if (/#include <stdio.h>|printf|scanf/.test(code)) return "C";
    if (/public class|System\.out\.println/.test(code)) return "Java";

    return "";
  };

  useEffect(() => {
    setDetectedLang(detectLanguage(code));
  }, [code]);

  /* -------- Explain -------- */
  const explainCode = async () => {

    if (!code.trim()) return;

    setLoadingExplain(true);
    setExplanation("");
    setUpdatedCode("");

    try {
      const res = await axios.post(
        "http://localhost:8000/explain",
        { code },
        { timeout: 300000 }
      );

      setExplanation(res.data.explanation);

    } catch {
      setExplanation("Backend not reachable.");
    }

    setLoadingExplain(false);
  };

  /* -------- Fix Bugs -------- */
  const fixBugs = async () => {

    if (!code.trim()) return;

    setLoadingFix(true);
    setExplanation("");
    setUpdatedCode("");

    try {
      const res = await axios.post(
        "http://localhost:8000/fix-bugs",
        { code }
      );

      setExplanation(res.data.explanation);
      setUpdatedCode(res.data.updatedCode);

    } catch {
      setExplanation("Bug fixing failed.");
    }

    setLoadingFix(false);
  };

  /* -------- Optimize -------- */
  const optimizeCode = async () => {

    if (!code.trim()) return;

    setLoadingOptimize(true);
    setExplanation("");
    setUpdatedCode("");

    try {
      const res = await axios.post(
        "http://localhost:8000/optimize-code",
        { code }
      );

      setExplanation(res.data.explanation);
      setUpdatedCode(res.data.updatedCode);

    } catch {
      setExplanation("Optimization failed.");
    }

    setLoadingOptimize(false);
  };

  /* -------- Convert -------- */
  const convertCode = async () => {

    if (!code.trim()) return;

    if (!targetLang) {
      alert("Select target language");
      return;
    }

    setLoadingConvert(true);
    setExplanation("");
    setUpdatedCode("");

    try {
      const res = await axios.post(
        "http://localhost:8000/convert-code",
        { code, targetLang }
      );

      setExplanation(res.data.explanation);
      setUpdatedCode(res.data.updatedCode);

    } catch {
      setExplanation("Conversion failed.");
    }

    setLoadingConvert(false);
  };

  /* -------- Copy -------- */
  const copyExplanation = () => {
    navigator.clipboard.writeText(explanation);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const copyUpdatedCode = () => {
    navigator.clipboard.writeText(updatedCode);
  };

  const allLanguages = ["Python", "JavaScript", "Java", "C++", "C"];

  const availableLanguages = allLanguages.filter(
    (lang) => lang !== detectedLang
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-900 to-blue-900 px-6 py-12">

      <div className="max-w-5xl mx-auto space-y-10">

        {/* HEADER */}
        <div className="text-center space-y-4">
          <h1 className="text-5xl font-bold text-white">
              CodeSage AI          
          </h1>
          <p className="text-slate-400">
            Explain, Debug, Optimize and Convert your code using AI.
          </p>
        </div>

        {/* CODE INPUT */}
        <div className="bg-slate-800 rounded-2xl p-6 border border-slate-700 shadow-xl space-y-4">

          <textarea
            className="w-full h-56 bg-transparent text-slate-100 font-mono text-sm outline-none resize-none"
            placeholder="Paste your code here..."
            value={code}
            onChange={(e) => setCode(e.target.value)}
          />

          <div className="flex flex-wrap gap-3 justify-end">

            {/* Explain */}
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={explainCode}
              disabled={isAnyLoading}
              className="px-5 py-2 rounded-xl bg-blue-600 text-white flex items-center gap-2"
            >
              {loadingExplain ? (
                <>
                  <Spinner />
                  Generating Explanation...
                </>
              ) : "Explain Code"}
            </motion.button>

            {/* Fix Bugs */}
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={fixBugs}
              disabled={isAnyLoading}
              className="px-5 py-2 rounded-xl bg-red-600 text-white flex items-center gap-2"
            >
              {loadingFix ? (
                <>
                  <Spinner />
                  Fixing Bugs...
                </>
              ) : "Fix Bugs/Errors"}
            </motion.button>

            {/* Optimize */}
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={optimizeCode}
              disabled={isAnyLoading}
              className="px-5 py-2 rounded-xl bg-green-600 text-white flex items-center gap-2"
            >
              {loadingOptimize ? (
                <>
                  <Spinner />
                  Optimizing...
                </>
              ) : "Optimize Code"}
            </motion.button>

            {/* Dropdown */}
            <select
              onChange={(e) => setTargetLang(e.target.value)}
              disabled={isAnyLoading}
              className="bg-slate-700 text-white rounded-xl px-3"
            >
              <option value="">Convert To</option>
              {availableLanguages.map((lang) => (
                <option key={lang}>{lang}</option>
              ))}
            </select>

            {/* Convert */}
            <motion.button
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              onClick={convertCode}
              disabled={isAnyLoading}
              className="px-5 py-2 rounded-xl bg-purple-600 text-white flex items-center gap-2"
            >
              {loadingConvert ? (
                <>
                  <Spinner />
                  Converting Code...
                </>
              ) : "Convert Code"}
            </motion.button>

          </div>
        </div>

        {/* EXPLANATION BOX */}
        <AnimatePresence>
          {explanation && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="bg-slate-800 rounded-2xl p-8 border border-slate-700 shadow-2xl"
            >
              <div className="flex justify-between mb-4">
                <h3 className="text-xl font-semibold text-white">
                  Explanation
                </h3>

                <button
                  onClick={copyExplanation}
                  className="text-xs px-3 py-1 bg-slate-700 rounded text-white"
                >
                  {copied ? "Copied!" : "Copy"}
                </button>
              </div>

              <div className="max-w-none text-slate-300 leading-relaxed space-y-4">

                <ReactMarkdown
                  remarkPlugins={[remarkGfm]}
                  components={{

                    h2: ({node, ...props}) => (
                      <h2 className="text-xl font-semibold text-white mt-6 mb-2" {...props} />
                    ),

                    h3: ({node, ...props}) => (
                      <h3 className="text-lg font-semibold text-white mt-5 mb-2" {...props} />
                    ),

                    p: ({node, ...props}) => (
                      <p className="mb-3 text-slate-300" {...props} />
                    ),

                    ul: ({node, ...props}) => (
                      <ul className="list-disc ml-6 mb-4 space-y-1" {...props} />
                    ),

                    li: ({node, ...props}) => (
                      <li className="text-slate-300" {...props} />
                    )

                  }}
                >
                  {cleanExplanation(explanation)}
                </ReactMarkdown>

              </div>

            </motion.div>
          )}
        </AnimatePresence>

        {/* UPDATED CODE BOX */}
        <AnimatePresence>
          {updatedCode && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="bg-slate-800 rounded-2xl p-8 border border-slate-700 shadow-2xl"
            >
              <div className="flex justify-between mb-4">
                <h3 className="text-xl font-semibold text-white">
                  Updated Code
                </h3>

                <button
                  onClick={copyUpdatedCode}
                  className="text-xs px-3 py-1 bg-slate-700 rounded text-white"
                >
                  Copy Code
                </button>
              </div>

              <pre className="bg-[#0f172a] p-5 rounded-xl overflow-x-auto text-sm whitespace-pre-wrap">
              <code className="text-green-400">
              {updatedCode}
  </code>
</pre>
            </motion.div>
          )}
        </AnimatePresence>

        <footer className="text-center text-slate-500 text-sm pt-10">
          Built with React · FastAPI · Ollama · Mistral
        </footer>

      </div>
    </div>
  );
}
